// 需求已确认放行。先补充核对几个数据点，确保档案内容准确。
const r1 = await tools.pwsh({
  description: "核对灵枢记忆各层数据量与 self 层状态",
  command: `
Write-Host '=== mdcg 各层文件数 ==='
Get-ChildItem "$env:DSH_HOME\\.dsh-memory\\data\\mdcg" -Directory | ForEach-Object {
  $n = (Get-ChildItem $_.FullName -File -Recurse -ErrorAction SilentlyContinue).Count
  "{0,-15} {1} 个文件" -f $_.Name, $n
}
Write-Host '=== self / anchor / structural / knowledge 层内容 ==='
foreach ($layer in @('self','anchor','structural','knowledge','goals')) {
  $p = "$env:DSH_HOME\\.dsh-memory\\data\\mdcg\\$layer"
  if (Test-Path $p) {
    Get-ChildItem $p -File | ForEach-Object { "--- $layer/$($_.Name) ($($_.Length)B) ---"; Get-Content $_.FullName -Raw }
  }
}
`
});
console.log(r1.stdout);
